<form method="post" class="rxp-form" style="margin-top:8px"><input type="hidden" name="action" value="password"><input type="hidden" name="child_id" value="<?=rxp_h($c['id'])?>"><div class="rxp-field"><label>رمز جدید</label><input type="password" name="password" minlength="8"></div><button class="rxp-btn">تنظیم رمز</button></form>
<form method="post" style="margin-top:12px"><input type="hidden" name="action" value="permissions"><input type="hidden" name="child_id" value="<?=rxp_h($c['id'])?>"><div class="rxp-form"><?php foreach(['products'=>'محصولات','categories'=>'دسته‌بندی','extend_user'=>'تمدید','charge_user'=>'شارژ مشتری','manage_users'=>'مدیریت مشتری','reports'=>'گزارش','set_prices'=>'قیمت‌گذاری','broadcast'=>'پیام‌رسانی','api'=>'API خواندنی','support'=>'تیکت پشتیبانی'] as $p=>$l):if(!rxp_can($ctx,$p))continue;?><label class="rxp-muted"><input type="checkbox" name="perm_<?=$p?>" <?=!empty($cp[$p])?'checked':''?>> <?=$l?></label><?php endforeach;?><button class="rxp-btn gray">ذخیره دسترسی</button></div></form>
<form method="post" style="margin-top:8px"><input type="hidden" name="action" value="status"><input type="hidden" name="child_id" value="<?=rxp_h($c['id'])?>"><input type="hidden" name="status" value="<?=$c['reseller_portal_status']==='disabled'?'active':'disabled'?>"><button class="rxp-btn red"><?=$c['reseller_portal_status']==='disabled'?'فعال‌سازی':'غیرفعال‌سازی پورتال'?></button></form></div><?php endforeach;?><?php if(!$children):?><div class="rxp-card rxp-muted">هنوز زیرنماینده مستقیمی ندارید.</div><?php endif;?><?php rxp_layout_end();
